g.script:
var H = SVGAnim.Helpers;
var IMAGEM = '../mapa brasil 1.jpg';
var CENTRO_X = 400;
var CENTRO_Y = 250;

var camada = H.get('camadaZoom');
var imagem = H.get('imgMapa');
var statusText = H.get('statusText');
var statusBg = H.get('statusBg');
var btnPlay = H.get('btnPlay');
var btnUpload = H.get('btnUpload');
var progressBar = H.get('progressBar');
var kfInfo = H.get('kfInfo');

imagem.setAttribute('href', IMAGEM);

btnUpload.addEventListener('click', function() {
  var fileInput = document.getElementById('fileInput');
  if (fileInput) fileInput.click();
});

document.addEventListener('change', function(event) {
  if (event.target && event.target.id === 'fileInput') {
    var file = event.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function(e) {
      imagem.setAttribute('href', e.target.result);
      statusText.textContent = 'Imagem carregada: ' + file.name + ' — pressione ▶ PLAY';
      salvarEstado();
    };
    reader.readAsDataURL(file);
  }
});

function salvarEstado() {
  try {
    var estado = {
      imagem: imagem.getAttribute('href')
    };
    var ids = [
      'zoomIniSlide','zoomFimSlide','zoomVelSlide',
      'blurIniSlide','blurFimSlide','blurVelSlide',
      'rotXIniSlide','rotYIniSlide','rotZIniSlide',
      'rotXFimSlide','rotYFimSlide','rotZFimSlide','rotVelSlide',
      'translTxIniSlide','translTyIniSlide',
      'translTxFimSlide','translTyFimSlide','translVelSlide'
    ];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) estado[ids[i]] = el.value;
    }
    var checks = ['chkZoom','chkBlur','chkRot','chkTransl'];
    for (var j = 0; j < checks.length; j++) {
      var ch = document.getElementById(checks[j]);
      if (ch) estado[checks[j]] = ch.checked;
    }
    estado['modoExibicao'] = modoExibicao;
    estado['duracaoSlide'] = g('duracaoSlide') ? g('duracaoSlide').value : 5;
    estado['tempoKF2Slide'] = g('tempoKF2Slide') ? g('tempoKF2Slide').value : 5;
    localStorage.setItem('SVG_ZOOM_STATE', JSON.stringify(estado));
  } catch(e) {}
}

function carregarEstado() {
  try {
    var json = localStorage.getItem('SVG_ZOOM_STATE');
    if (!json) return;
    var estado = JSON.parse(json);

    if (estado.imagem) {
      imagem.setAttribute('href', estado.imagem);
    }

    var ids = [
      'zoomIniSlide','zoomFimSlide','zoomVelSlide',
      'blurIniSlide','blurFimSlide','blurVelSlide',
      'rotXIniSlide','rotYIniSlide','rotZIniSlide',
      'rotXFimSlide','rotYFimSlide','rotZFimSlide','rotVelSlide',
      'translTxIniSlide','translTyIniSlide',
      'translTxFimSlide','translTyFimSlide','translVelSlide'
    ];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el && estado[ids[i]] !== undefined) el.value = estado[ids[i]];
    }

    var checks = ['chkZoom','chkBlur','chkRot','chkTransl'];
    for (var j = 0; j < checks.length; j++) {
      var ch = document.getElementById(checks[j]);
      if (ch && estado[checks[j]] !== undefined) ch.checked = estado[checks[j]];
    }

    if (estado['modoExibicao'] !== undefined) {
      modoExibicao = estado['modoExibicao'];
      var checkEl = document.getElementById('modoExibCheck');
      if (checkEl) checkEl.textContent = modoExibicao ? '\u2713' : '';
    }

    if (estado['duracaoSlide'] !== undefined) {
      g('duracaoSlide').value = estado['duracaoSlide'];
      g('tempoKF2Slide').max = estado['duracaoSlide'];
    }
    if (estado['tempoKF2Slide'] !== undefined) {
      g('tempoKF2Slide').value = estado['tempoKF2Slide'];
    }
  } catch(e) {}
}

var T_BAR_X = 40;
var T_BAR_W = 720;

var camera = new SVGAnim.Camera({
  zoom: 1.0,
  zoomSmoothness: 0.02,
  zoomCenterX: CENTRO_X,
  zoomCenterY: CENTRO_Y,
  blur: 7,
  blurSmoothness: 0.02,
  blurFilterId: 'blurElem',
  rotationX: -25,
  rotationY: 15,
  rotationZ: 0,
  rotationSmoothness: 0.02,
  perspective: 800
});

var rodando = false;
var kfSelecionado = 1;
var modoExibicao = false;

var zoomEnabled = true;
var blurEnabled = true;
var rotEnabled = true;
var translEnabled = true;

var targetZoom = 1.5;
var targetBlur = 0;
var targetRotX = 0;
var targetRotY = 0;
var targetRotZ = 0;
var targetTx = 0;
var targetTy = 0;

var zoomIni = 1.0;
var blurIni = 7;
var rotXIni = -25;
var rotYIni = 15;
var rotZIni = 0;
var txIni = 0;
var tyIni = 0;

var duracaoTotal = 5;
var tempoKF2 = 5;

function lerSliders() {
  var el;
  targetZoom = (el = g('zoomFimSlide')) ? (el.value / 10) : 1.5;
  zoomIni = (el = g('zoomIniSlide')) ? (el.value / 10) : 1.0;

  targetBlur = (el = g('blurFimSlide')) ? parseInt(el.value) : 0;
  blurIni = (el = g('blurIniSlide')) ? parseInt(el.value) : 7;

  targetRotX = (el = g('rotXFimSlide')) ? parseInt(el.value) : 0;
  targetRotY = (el = g('rotYFimSlide')) ? parseInt(el.value) : 0;
  targetRotZ = (el = g('rotZFimSlide')) ? parseInt(el.value) : 0;
  rotXIni = (el = g('rotXIniSlide')) ? parseInt(el.value) : -25;
  rotYIni = (el = g('rotYIniSlide')) ? parseInt(el.value) : 15;
  rotZIni = (el = g('rotZIniSlide')) ? parseInt(el.value) : 0;

  targetTx = (el = g('translTxFimSlide')) ? parseInt(el.value) : 0;
  targetTy = (el = g('translTyFimSlide')) ? parseInt(el.value) : 0;
  txIni = (el = g('translTxIniSlide')) ? parseInt(el.value) : 0;
  tyIni = (el = g('translTyIniSlide')) ? parseInt(el.value) : 0;

  camera.zoomSmoothness = (el = g('zoomVelSlide')) ? (el.value / 1000) : 0.02;
  camera.blurSmoothness = (el = g('blurVelSlide')) ? (el.value / 1000) : 0.02;
  camera.rotationSmoothness = (el = g('rotVelSlide')) ? (el.value / 1000) : 0.02;
  camera.translateSmoothness = (el = g('translVelSlide')) ? (el.value / 1000) : 0.02;

  duracaoTotal = (el = g('duracaoSlide')) ? parseInt(el.value) : 5;
  tempoKF2 = (el = g('tempoKF2Slide')) ? parseFloat(el.value) : 5;
  if (tempoKF2 > duracaoTotal) tempoKF2 = duracaoTotal;
  if (tempoKF2 < 0.5) tempoKF2 = 0.5;

  zoomEnabled = g('chkZoom') ? g('chkZoom').checked : true;
  blurEnabled = g('chkBlur') ? g('chkBlur').checked : true;
  rotEnabled = g('chkRot') ? g('chkRot').checked : true;
  translEnabled = g('chkTransl') ? g('chkTransl').checked : true;

  aplicarValoresAtuais();
}

function g(id) { return document.getElementById(id); }

function atualizarLabelsSliders() {
  var zis = g('zoomIniSlide'); if (zis) g('lblZoomIni').textContent = (zis.value/10).toFixed(1);
  var zfs = g('zoomFimSlide'); if (zfs) g('lblZoomFim').textContent = (zfs.value/10).toFixed(1);
  var zvs = g('zoomVelSlide'); if (zvs) g('lblZoomVel').textContent = (zvs.value/1000).toFixed(3);
  var bis = g('blurIniSlide'); if (bis) g('lblBlurIni').textContent = bis.value;
  var bfs = g('blurFimSlide'); if (bfs) g('lblBlurFim').textContent = bfs.value;
  var bvs = g('blurVelSlide'); if (bvs) g('lblBlurVel').textContent = (bvs.value/1000).toFixed(3);
  var rxi = g('rotXIniSlide'); if (rxi) g('lblRotXIni').textContent = rxi.value;
  var ryi = g('rotYIniSlide'); if (ryi) g('lblRotYIni').textContent = ryi.value;
  var rzi = g('rotZIniSlide'); if (rzi) g('lblRotZIni').textContent = rzi.value;
  var rxf = g('rotXFimSlide'); if (rxf) g('lblRotXFim').textContent = rxf.value;
  var ryf = g('rotYFimSlide'); if (ryf) g('lblRotYFim').textContent = ryf.value;
  var rzf = g('rotZFimSlide'); if (rzf) g('lblRotZFim').textContent = rzf.value;
  var txi = g('translTxIniSlide'); if (txi) g('lblTranslTxIni').textContent = txi.value;
  var tyi = g('translTyIniSlide'); if (tyi) g('lblTranslTyIni').textContent = tyi.value;
  var txf = g('translTxFimSlide'); if (txf) g('lblTranslTxFim').textContent = txf.value;
  var tyf = g('translTyFimSlide'); if (tyf) g('lblTranslTyFim').textContent = tyf.value;
  var tvl = g('translVelSlide'); if (tvl) g('lblTranslVel').textContent = (tvl.value/1000).toFixed(3);
  var dur = g('duracaoSlide'); if (dur) { g('lblDuracao').textContent = dur.value + 's'; g('tempoKF2Slide').max = dur.value; if (parseFloat(g('tempoKF2Slide').value) > parseInt(dur.value)) g('tempoKF2Slide').value = dur.value; }
  var t2 = g('tempoKF2Slide'); if (t2) g('lblTempoKF2').textContent = parseFloat(t2.value).toFixed(1) + 's';
  g('duracaoLabel').textContent = duracaoTotal.toFixed(1);
  g('tempoKF2Label').textContent = tempoKF2.toFixed(1) + 's';
  posicionarKF2();
}

function atualizarPosicaoTimeline() {
  if (duracaoTotal <= 0) return;
  var xFim = 40 + 720 * (tempoKF2 / duracaoTotal);
  xFim = Math.max(40, Math.min(760, xFim));
  g('kf2Outer').setAttribute('cx', xFim);
  g('kf2Inner').setAttribute('cx', xFim);
  g('fimLabel').setAttribute('x', xFim);
  g('tempoKF2Label').setAttribute('x', xFim);
}

function atualizarKFInfo() {
  if (kfSelecionado === 1) {
    kfInfo.textContent =
    'KF1 (Inicial, 0.0s): Zoom ' + zoomIni.toFixed(1) +
    ' | Blur ' + blurIni +
    ' | Pitch ' + rotXIni + '°  Yaw ' + rotYIni +
    '°  Roll ' + rotZIni + '°' +
    ' | Tx ' + txIni + '  Ty ' + tyIni;
  } else {
    kfInfo.textContent =
    'KF2 (Final, ' + tempoKF2.toFixed(1) + 's): Zoom ' + targetZoom.toFixed(1) +
    ' | Blur ' + targetBlur +
    ' | Pitch ' + targetRotX + '°  Yaw ' + targetRotY +
    '°  Roll ' + targetRotZ + '°' +
    ' | Tx ' + targetTx + '  Ty ' + targetTy;
  }
}

function aplicarValoresAtuais() {
  if (rodando) return;

  if (kfSelecionado === 1) {
    camera.zoom = zoomIni;
    camera._targetZoom = zoomIni;
    camera.blur = blurIni;
    camera._targetBlur = blurIni;
    camera.rotationX = rotXIni;
    camera._targetRotationX = rotXIni;
    camera.rotationY = rotYIni;
    camera._targetRotationY = rotYIni;
    camera.rotationZ = rotZIni;
    camera._targetRotationZ = rotZIni;
    camera.tx = txIni;
    camera._targetTx = txIni;
    camera.ty = tyIni;
    camera._targetTy = tyIni;
  } else {
    camera.zoom = targetZoom;
    camera._targetZoom = targetZoom;
    camera.blur = targetBlur;
    camera._targetBlur = targetBlur;
    camera.rotationX = targetRotX;
    camera._targetRotationX = targetRotX;
    camera.rotationY = targetRotY;
    camera._targetRotationY = targetRotY;
    camera.rotationZ = targetRotZ;
    camera._targetRotationZ = targetRotZ;
    camera.tx = targetTx;
    camera._targetTx = targetTx;
    camera.ty = targetTy;
    camera._targetTy = targetTy;
  }

  if (camera.blurFilterId) {
    var filterEl = document.getElementById(camera.blurFilterId);
    if (filterEl) {
      filterEl.setAttribute('stdDeviation', camera.blur);
    }
  }

  camada.style.transform = camera.getCameraTransform();
  camada.style.transformOrigin = '0 0';
  atualizarStatus();
}

function atualizarStatus() {
  statusText.textContent =
    'Zoom: ' + camera.zoom.toFixed(2) + 'x  |  ' +
    'Blur: ' + camera.blur.toFixed(1) + 'px  |  ' +
    'Pitch: ' + camera.rotationX.toFixed(1) + '°  ' +
    'Yaw: ' + camera.rotationY.toFixed(1) + '°  ' +
    'Roll: ' + camera.rotationZ.toFixed(1) + '°  ' +
    'Tx: ' + camera.tx.toFixed(0) + '  Ty: ' + camera.ty.toFixed(0);
}

function atualizarProgressBar(prog) {
  progressBar.setAttribute('width', prog * T_BAR_W);
}

function posicionarKF2() {
  var tx = T_BAR_X + (tempoKF2 / Math.max(duracaoTotal, 1)) * T_BAR_W;
  tx = Math.max(T_BAR_X, Math.min(T_BAR_X + T_BAR_W, tx));
  setKF2PositionPX(tx);
}

function setKF2PositionPX(px) {
  px = Math.max(T_BAR_X, Math.min(T_BAR_X + T_BAR_W, px));
  g('kf2Outer').setAttribute('cx', px);
  g('kf2Inner').setAttribute('cx', px);
  g('fimLabel').setAttribute('x', px);
  g('tempoKF2Label').setAttribute('x', px);
  g('kf2Tick').setAttribute('x1', px);
  g('kf2Tick').setAttribute('x2', px);
}

var inicioTimestamp = null;

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function animar(timestamp) {
  if (inicioTimestamp === null) inicioTimestamp = timestamp;
  var decorrido = Math.min((timestamp - inicioTimestamp) / 1000, tempoKF2);
  var fator = tempoKF2 > 0 ? decorrido / tempoKF2 : 1.0;

  if (zoomEnabled) camera.zoom = lerp(zoomIni, targetZoom, fator);
  if (blurEnabled) camera.blur = lerp(blurIni, targetBlur, fator);
  if (rotEnabled) {
    camera.rotationX = lerp(rotXIni, targetRotX, fator);
    camera.rotationY = lerp(rotYIni, targetRotY, fator);
    camera.rotationZ = lerp(rotZIni, targetRotZ, fator);
  }
  if (translEnabled) {
    camera.tx = lerp(txIni, targetTx, fator);
    camera.ty = lerp(tyIni, targetTy, fator);
  }

  if (camera.blurFilterId) {
    var filterEl = document.getElementById(camera.blurFilterId);
    if (filterEl) filterEl.setAttribute('stdDeviation', camera.blur);
  }

  camada.style.transform = camera.getCameraTransform();
  camada.style.transformOrigin = '0 0';
  atualizarStatus();

  var kf2X = parseFloat(g('kf2Outer').getAttribute('cx'));
  progressBar.setAttribute('width', Math.max(0, (kf2X - T_BAR_X) * fator));

  if (decorrido < tempoKF2) {
    requestAnimationFrame(animar);
  } else {
    var kf2XEnd = parseFloat(g('kf2Outer').getAttribute('cx'));
    progressBar.setAttribute('width', Math.max(0, kf2XEnd - T_BAR_X));
    rodando = false;
    setKFSelection(2);
    if (modoExibicao) {
      H.get('toolbars').setAttribute('display', 'inline');
      H.get('modoExibicao').setAttribute('display', 'inline');
    }
    g('playLabel').textContent = '\u25B6';
    statusBg.setAttribute('fill', 'rgba(0,0,0,0.55)');
    statusText.textContent = 'Animação concluída — ajuste os parâmetros e pressione ▶ PLAY';
  }
}

function iniciar() {
  if (rodando) return;
  lerSliders();

  if (zoomEnabled) {
    camera.zoom = zoomIni;
  } else {
    camera._targetZoom = camera.zoom;
  }

  if (blurEnabled) {
    camera.blur = blurIni;
  } else {
    camera._targetBlur = camera.blur;
  }

  if (rotEnabled) {
    camera.rotationX = rotXIni;
    camera.rotationY = rotYIni;
    camera.rotationZ = rotZIni;
  } else {
    camera._targetRotationX = camera.rotationX;
    camera._targetRotationY = camera.rotationY;
    camera._targetRotationZ = camera.rotationZ;
  }

  if (translEnabled) {
    camera.tx = txIni;
    camera.ty = tyIni;
  } else {
    camera._targetTx = camera.tx;
    camera._targetTy = camera.ty;
  }

  progressBar.setAttribute('width', '0');
  if (modoExibicao) {
    H.get('toolbars').setAttribute('display', 'none');
    H.get('modoExibicao').setAttribute('display', 'none');
  }
  inicioTimestamp = null;
  rodando = true;
  g('playLabel').textContent = '\u25A0';
  statusBg.setAttribute('fill', 'rgba(76,175,80,0.6)');
  requestAnimationFrame(animar);
}

function setKFSelection(kf) {
  kfSelecionado = kf;
  var k1o = g('kf1Outer');
  var k1i = g('kf1Inner');
  var k2o = g('kf2Outer');
  var k2i = g('kf2Inner');

  if (kf === 1) {
    k1o.setAttribute('stroke', '#4CAF50'); k1o.setAttribute('stroke-width', '2.5');
    k1i.setAttribute('display', 'inline');
    k2o.setAttribute('stroke', '#aaa'); k2o.setAttribute('stroke-width', '2');
    k2i.setAttribute('display', 'none');
  } else {
    k2o.setAttribute('stroke', '#4CAF50'); k2o.setAttribute('stroke-width', '2.5');
    k2i.setAttribute('display', 'inline');
    k1o.setAttribute('stroke', '#aaa'); k1o.setAttribute('stroke-width', '2');
    k1i.setAttribute('display', 'none');
  }

  var kf1Fields = document.querySelectorAll('.kf1-field');
  var kf2Fields = document.querySelectorAll('.kf2-field');
  for (var i = 0; i < kf1Fields.length; i++) {
    kf1Fields[i].style.display = (kf === 1) ? 'flex' : 'none';
  }
  for (var j = 0; j < kf2Fields.length; j++) {
    kf2Fields[j].style.display = (kf === 2) ? 'flex' : 'none';
  }

  atualizarKFInfo();
  aplicarValoresAtuais();
}

btnPlay.addEventListener('click', iniciar);

H.get('kf1').addEventListener('click', function() { setKFSelection(1); });
H.get('kf2').addEventListener('click', function() { setKFSelection(2); });

document.addEventListener('keydown', function(event) {
  var active = document.activeElement;
  if (active && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA')) return;
  if (event.code === 'Home') {
    event.preventDefault();
    if (!rodando) setKFSelection(1);
  }
  if (event.code === 'End') {
    event.preventDefault();
    if (!rodando) setKFSelection(2);
  }
  if (event.code === 'Space') {
    event.preventDefault();
    iniciar();
  }
});

var arrastando = false;
var mouseIniX = 0;
var mouseIniY = 0;
var txAnchor = 0;
var tyAnchor = 0;
var draggingKF2 = false;
var kf2AnchorTime = 0;

H.get('overlayMouse').addEventListener('mousedown', function(e) {
  if (rodando) return;

  arrastando = true;
  mouseIniX = e.clientX;
  mouseIniY = e.clientY;
  lerSliders();
  txAnchor = (kfSelecionado === 1) ? txIni : targetTx;
  tyAnchor = (kfSelecionado === 1) ? tyIni : targetTy;
});

H.get('kf2').addEventListener('mousedown', function(e) {
  if (rodando) return;
  e.stopPropagation();
  draggingKF2 = true;
  kf2AnchorTime = tempoKF2;
  mouseIniX = e.clientX;
});

window.addEventListener('mousemove', function(e) {
  if (draggingKF2 && !rodando) {
    var rect = H.get('svgRaiz').getBoundingClientRect();
    var scaleX = 800 / rect.width;
    var dx = (e.clientX - mouseIniX) * scaleX;
    var rawTempo = kf2AnchorTime + (dx / T_BAR_W) * duracaoTotal;
    rawTempo = Math.max(0.5, Math.min(duracaoTotal, rawTempo));
    var posX = T_BAR_X + (rawTempo / duracaoTotal) * T_BAR_W;
    setKF2PositionPX(posX);

    var rounded = Math.round(rawTempo * 10) / 10;
    g('tempoKF2Slide').value = rounded;
    g('lblTempoKF2').textContent = rounded.toFixed(1) + 's';
    g('tempoKF2Label').textContent = rounded.toFixed(1) + 's';
    return;
  }
  if (!arrastando || rodando) return;
  var dx = e.clientX - mouseIniX;
  var dy = e.clientY - mouseIniY;
  var novoTx = Math.round(Math.max(-300, Math.min(300, txAnchor + dx)));
  var novoTy = Math.round(Math.max(-300, Math.min(300, tyAnchor + dy)));
  var txId = (kfSelecionado === 1) ? 'translTxIniSlide' : 'translTxFimSlide';
  var tyId = (kfSelecionado === 1) ? 'translTyIniSlide' : 'translTyFimSlide';
  g(txId).value = novoTx;
  g(tyId).value = novoTy;
  lerSliders();
  atualizarLabelsSliders();
  atualizarKFInfo();
  aplicarValoresAtuais();
  salvarEstado();
});

window.addEventListener('mouseup', function(e) {
  arrastando = false;
  if (draggingKF2) {
    draggingKF2 = false;
    var finalTempo = Math.max(0.5, Math.min(duracaoTotal, Math.round(tempoKF2 * 10) / 10));
    g('tempoKF2Slide').value = parseFloat(g('tempoKF2Slide').value);
    lerSliders();
    atualizarLabelsSliders();
    atualizarKFInfo();
    salvarEstado();
  }
});

H.get('overlayMouse').addEventListener('wheel', function(e) {
  if (rodando || !e.ctrlKey) return;
  e.preventDefault();
  lerSliders();
  var zoomId = (kfSelecionado === 1) ? 'zoomIniSlide' : 'zoomFimSlide';
  var zoomAtual = parseInt(g(zoomId).value);
  var delta = e.deltaY < 0 ? 1 : -1;
  var novo = Math.max(10, Math.min(30, zoomAtual + delta));
  g(zoomId).value = novo;
  lerSliders();
  atualizarLabelsSliders();
  atualizarKFInfo();
  aplicarValoresAtuais();
  salvarEstado();
});

var arrastandoKF2 = false;
H.get('kf2').addEventListener('mousedown', function(e) {
  if (rodando) return;
  e.stopPropagation();
  arrastandoKF2 = true;
  H.get('kf2').setAttribute('cursor', 'grabbing');
});

window.addEventListener('mousemove', function(e) {
  if (!arrastandoKF2 || rodando) return;
  var rect = H.get('svgRaiz').getBoundingClientRect();
  var svgX = (e.clientX - rect.left) / rect.width * 800;
  var novoX = Math.max(40, Math.min(760, svgX));
  var novoTempo = duracaoTotal > 0 ? ((novoX - 40) / 720) * duracaoTotal : 0;
  novoTempo = Math.max(0.5, Math.min(duracaoTotal, Math.round(novoTempo * 2) / 2));
  var el = g('tempoKF2Slide');
  if (el) el.value = novoTempo;
  lerSliders();
  atualizarLabelsSliders();
  atualizarKFInfo();
  aplicarValoresAtuais();
  salvarEstado();
});

window.addEventListener('mouseup', function(e) {
  if (arrastandoKF2) {
    arrastandoKF2 = false;
    H.get('kf2').setAttribute('cursor', 'grab');
  }
});

function setupSliderListeners() {
  var sliders = document.querySelectorAll('input[type=range], input[type=checkbox]');
  for (var i = 0; i < sliders.length; i++) {
    sliders[i].addEventListener('input', function() {
      lerSliders();
      atualizarLabelsSliders();
      atualizarKFInfo();
      aplicarValoresAtuais();
      salvarEstado();
    });
  }
}

var panelReady = false;
function initQuandoPronto() {
  if (panelReady) return;
  if (!g('zoomIniSlide')) return;
  panelReady = true;
  carregarEstado();
  setupSliderListeners();
  lerSliders();
  atualizarLabelsSliders();
  atualizarKFInfo();
  atualizarStatus();
  posicionarKF2();

  H.get('modoExibicao').addEventListener('click', function() {
    modoExibicao = !modoExibicao;
    var checkEl = H.get('modoExibCheck');
    checkEl.textContent = modoExibicao ? '\u2713' : '';
  });
}
setTimeout(function() { initQuandoPronto(); }, 200);
var pollTimer = setInterval(function() {
  if (!panelReady) initQuandoPronto();
  else clearInterval(pollTimer);
}, 100);

camada.style.transform = camera.getCameraTransform();
camada.style.transformOrigin = '0 0';
atualizarStatus();

div.style:
font-family: Arial, sans-serif; font-size: 11px; color: #eee;
background: rgba(20,20,20,0.85); padding: 6px 8px;
box-sizing: border-box; width: 800px; user-select: none;
overflow: visible;
